// Auto-generated from user .hsmlib Fusion 360 tool libraries
// Real-world proven cutting parameters from actual CNC machines
// These are GOLD — tested on physical machines in production

export type ProvenToolType = 'flat_end_mill' | 'bull_nose_end_mill' | 'ball_end_mill' | 'face_mill' | 'spot_drill' | 'drill' | 'tap_right_hand' | 'tap_left_hand' | 'reamer' | 'boring_bar' | 'counter_bore' | 'counter_sink' | 'chamfer_mill' | 'lollipop_mill' | 'thread_mill' | 'dovetail_mill' | 'slot_mill' | 'radius_mill' | 'tapered_mill' | 'probe';

export interface ProvenCuttingRecord {
  machine: string;
  material: string;
  operation: string;
  sourceLibrary: string;
  toolDescription: string;
  toolType: ProvenToolType;
  toolMaterial: string;  // 'carbide' | 'hss' | 'ti coated' etc.
  unit: 'inches' | 'millimeters';
  diameter: number;
  shaftDiameter: number;
  fluteLength: number;
  overallLength: number;
  numberOfFlutes: number;
  cornerRadius: number;
  coolant: string;
  rpm: number;
  feedRate: number;  // in/min or mm/min matching unit
  plungeFeed: number;
  rampFeed: number;
  rampRpm: number;
  // Preset values (may differ from motion — presets are the saved user values)
  presetRpm: number;
  presetFeedCutting: number;  // mm/min (Fusion stores presets in metric)
  presetFeedPlunge: number;
  presetStepdown: number;  // DOC, 0 if not set
  presetStepover: number;  // WOC, 0 if not set
}

